/**
 * Why does this file exist? It is kv-pager's page table behind a C ABI (native/kv-pager-wasm), the prompt-prefix page table prefixCache.ts asks, compiled to WebAssembly
 * and carried here as base64 so the single-file build needs no cargo and no loader: 53133 bytes, SHA-256
 * bcec480ff1dfb91e9002dd8d5ee51a0e2f9416856f9e7b8752641f70959db1e9.
 * GENERATED by tools/native/build-wasm.mjs (npm run native:wasm) from native/kv-pager-wasm; do not edit by hand.
 * What breaks if it is removed? prefixCache.ts has no table: the router's ask status has no cache line.
 */
export const KV_PAGER_WASM_BYTES = 53133
export const KV_PAGER_WASM_SHA256 = 'bcec480ff1dfb91e9002dd8d5ee51a0e2f9416856f9e7b8752641f70959db1e9'
export const KV_PAGER_WASM_BASE64 =
  ''
